def main():
    assert set(PREDS.keys()) == set(IDS), (sorted(PREDS.keys()), IDS)
    assert len(PREDS) == 20
    os.makedirs(OUT, exist_ok=True)
    n = 0
    for cid in IDS:
        p = PREDS[cid]
        rec = {"case_id": cid, "prediction_text": p["prediction_text"],
               "basis": p["basis"], "confidence": p["confidence"],
               "trigger": p["trigger"]}
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20
    print("WROTE", n)

if __name__ == "__main__":
    main()
